import { packagesPrimer } from './foundations.mjs';
import { collisionTestLesson } from './reader-tests.mjs';
import {p, section as s, code, extract, note, table, list, snippet as q, frame, mistakes, experiments, flow} from './html.mjs';
export const roomChapters = [];
const chapter = (number,slug,title,deck,outcome,body) => roomChapters.push({number,slug,part:'V · A room worth walking through',title,deck,outcome,body});

chapter(19,'pixels-from-a-picture','Pixels from a picture',
  'Upload a room and a transparent character. Replace shader-drawn facial features with sampled color, without changing what a triangle does.',
  'The same native application displays a furnished pixel-art room and a moving pixel-art character. Furniture is intentionally not solid yet.',
  s('Add the room artwork',p(`Our geometric character already moves in a native window. Now we will use pictures for its appearance and surroundings. The room image contains a bed, tables, bookshelf, chair, chest, and plant. The player will move over that image using the same input and seconds-based update we already wrote. In this chapter the furniture is only painted scenery; collision comes after drawing the room works.`)
  + p(`We will reuse the native window, surface, device, and frame-lifetime code. The drawing data changes because we need a background and a player with different images and positions. Work through the sections in order. They explain the replacement renderer in parts, and the complete file listings at the end put those parts together.`)
  + `<figure class="art-preview"><img src="../project/assets/room.png" width="1536" height="1024" alt="Top-down pixel-art room with bed, tables, bookshelf, chair, chest, rug, and plant"><figcaption>The room texture. Furniture colors are artwork, not collision information.</figcaption></figure>`
  + p(`The room contains 1536 × 1024 source pixels. The player image is 1254 × 1254 and includes an alpha channel for transparent surroundings. Both PNG files are included as book attachments. Create an <code>assets</code> directory beside src, then save <a download="room.png" href="../project/assets/room.png">room.png</a> and <a download="player.png" href="../project/assets/player.png">player.png</a> there. Save the original files, not screenshots of their previews; screenshots may discard transparency. The application will embed these images when it builds.`)
  + p(`The artwork has a pixel-art style, but its source pixels do not form a uniform low-resolution game grid. Nearest sampling, introduced below, keeps neighboring texels from blending together. It cannot repair uneven detail in an image. We will keep the source images unchanged and choose their displayed size in world units.`))
  + packagesPrimer
  + s('First, move the files on purpose',table(['Chapter 18','Chapter 19','Reason'],[
    ['src/platform.odin','renderer/platform.odin','The renderer owns the SDL-to-WebGPU bridge. Only the package declaration changes.'],
    ['src/gpu.odin','renderer/gpu.odin','Retain all capability, callback, resize, and lifetime machinery. Only the package declaration changes.'],
    ['src/renderer.odin','renderer/renderer.odin + renderer/texture.odin','Replace the one-character renderer with bounded sprite recording and explicit uploads.'],
    ['shaders/character.wgsl','renderer/sprites.wgsl','Replace procedural facial features with a sampled texture.'],
    ['src/game.odin','game/game.odin','Game owns position, speed, and asset choices; SDL key sampling moves to main.'],
    ['src/main.odin','src/main.odin','Main imports the two packages and maps SDL state into game.Input.'],
  ]) + p(`Create <code>renderer</code> and <code>game</code> directories beside src. Move platform.odin and gpu.odin into renderer and change the first line of each to <code>package renderer</code>; leave their procedures unchanged. Replace the old drawing code using the new renderer/renderer.odin, renderer/texture.odin, and renderer/sprites.wgsl listings. Create game/game.odin with <code>package game</code>. The replacement src/main.odin uses <code>package room</code> to name the application package; the entry procedure is still main. Replace that file, then remove src/renderer.odin, src/game.odin, and shaders/character.wgsl. The obsolete shaders directory can remain empty. Build src as before; Odin follows its relative imports automatically.`)
  + p(`The file lists at the end show the complete package layout, including imports. src/main.odin imports renderer and game. game/game.odin imports renderer, while renderer never imports game. That direction lets the game request a picture without making the graphics code depend on movement rules.`))
  + s('Choose a point in a picture', flow('A file becomes pixels before the shader can read it.', ['PNG bytes', 'Decoded RGBA pixels', 'GPU texture', 'Sampled color'])
  + p(`A PNG file stores a compressed image. Decoding expands it into pixels in CPU memory. Uploading copies those pixels to a GPU texture. A texel is one pixel in a texture; it need not cover exactly one window pixel. For example, the 1536 × 1024 room will occupy 384 × 256 world units, so there are four source texels along each world unit.`)
  + p(`UV coordinates select a point in a texture. U runs left to right and V runs top to bottom. Both run from 0 to 1 across the whole image. The upper-left corner uses (0,0), the lower-right uses (1,1), and the center uses (0.5,0.5). Four UV corners on the rectangle let rasterization find a coordinate for each covered fragment.`)
  + p(`A texture view gives the shader access to the image, and a sampler determines how a UV coordinate chooses a texel. We choose nearest filtering: read the nearest texel instead of blending its neighbors. ClampToEdge holds coordinates at the image edge instead of repeating the picture. We use one full-resolution image level, called mip level zero; there are no smaller precomputed versions.`))
  + s('Two groups, two responsibilities',table(['WGSL address','Odin resource','Purpose'],[
    ['@group(0) @binding(0)','view_buffer through view_group','World extent shared by every sprite in the frame.'],
    ['@group(1) @binding(0)','Texture_Slot.view','The sampled room, player, or white texture.'],
    ['@group(1) @binding(1)','State.sampler','Nearest filtering and clamped UV addressing.'],
  ]) + q(19,"renderer/renderer.odin","    texture_entries :=","    layouts :=","renderer/renderer.odin · Init · texture binding layout","Inside Init, place this block after r.view_group = wgpu.DeviceCreateBindGroup and before layouts :=. It creates the second bind-group layout; keep the view layout and pipeline setup from the complete file.")
  + p(`Inside <code>renderer.Init</code>, the texture layout declares a filterable floating-point 2D image and a filtering-compatible sampler, both visible only to the fragment stage. “Filtering” here is an allowed binding class, not a command to interpolate neighboring pixels. The concrete sampler chooses <code>Nearest</code> for minification and magnification. <code>ClampToEdge</code> prevents wrapping across UV boundaries. Mip clamps and a single texture level keep the sampling policy explicit.`)
  + p(`The pipeline layout receives the view layout first and the texture layout second, matching group indices 0 and 1. Every loaded image gets a bind group conforming to the same texture layout. Switching images therefore requires changing group 1, not creating another pipeline. The pipeline’s target still matches the acquired surface view; the texture input format belongs to a different side of the pipeline.`))
  + s('The new vertex contract',table(['Odin memory','Vertex layout','WGSL vertex input'],[
    ['position: [2]f32, bytes 0–7','Float32x2, offset 0, location 0','@location(0) position: vec2f'],
    ['uv: [2]f32, bytes 8–15','Float32x2, offset 8, location 1','@location(1) uv: vec2f'],
    ['tint: [4]f32, bytes 16–31','Float32x4, offset 16, location 2','@location(2) tint: vec4f'],
    ['Next vertex begins 32 bytes later','arrayStride = 32, stepMode = Vertex','One complete input record per indexed vertex'],
  ]) + p(`Replace the old 24-byte position/color vertex with this 32-byte record. The four corners receive the full-image UVs introduced above. Rasterization interpolates them across the triangles, letting each fragment sample the appropriate part of the picture. Shader output location 0 carries UV to fragment input location 0; it does not need to match the vertex attribute’s location 1. Locations connect a particular pair of pipeline stages, not a globally named property.`)
  + q(19,'renderer/sprites.wgsl')
  + p(`The vertex shader receives already positioned world-space corners. The CPU expands each sprite rectangle; the shader applies the same world-to-NDC conversion we already know. We removed per-character transform uniforms because position now belongs to each vertex record. The 16-byte view uniform contains a vec2 extent and an explicit vec2 padding field; Odin alignment and size assertions match WGSL.`)
  + p(`The fragment shader’s <code>textureSample</code> reads filtered-by-the-sampler color and multiplies it by a linear tint. The PNG decoder produces straight-alpha pixels, and the existing straight-alpha blend factors are retained. An alpha-zero fragment contributes no source RGB to the framebuffer. Do not multiply RGB by alpha in this shader unless you also switch to a premultiplied-alpha blend convention. The surface’s sRGB format encodes the linear blended result for display.`))
  + s('Decode the file and upload its pixels', p(`Create <code>renderer/texture.odin</code>. It has two procedures: Load_PNG turns compressed image bytes into pixels, and upload_rgba puts those pixels in GPU storage. The complete file includes the fmt, core:c, stbi, and wgpu imports. Read the two jobs separately before adding their code.`)
  + q(19,'renderer/texture.odin','Load_PNG :: proc')
  + p(`Add this procedure in <code>renderer/texture.odin</code>. <code>vendor:stb/image</code> is the pinned Odin distribution’s native image decoder binding; it introduces no new downloaded library and hides no WebGPU calls. <code>#load(..., []u8)</code> in <code>game.Init</code> embeds the PNG bytes at compile time, so launching from a different working directory still works. Changing a PNG requires rebuilding. This simple asset policy is intentional, not a runtime asset manager.`)
  + p(`The decoder takes an address and a C integer byte count. The first checks reject an empty image or a count too large for that integer. It then reads the header and checks positive width and height against the device’s texture-size limit before allocating pixels. Asking for four output channels gives both images the same RGBA byte layout; the RGB room receives alpha 255. <code>channels</code> reports the original file’s channel count. The decoder owns the returned allocation, so <code>stbi.image_free</code> releases it after upload.`)
  + p(`In <code>renderer/texture.odin</code>, add <code>upload_rgba</code> after <code>Load_PNG</code>, at file scope. This first excerpt shows only its opening. The comment marks omitted statements: put the next two snippets there, inside the same procedure, before its final closing brace. Do not leave the placeholder comment as the implementation. The <a href="#source-renderer-texture-odin">complete file</a> shows all three parts joined together, with the imports and private annotation.`)
  + code(extract(19,'renderer/texture.odin','upload_rgba :: proc','    destination :=') + '\n    // Continue here with the upload and bind-group blocks below.\n}', 'odin', 'renderer/texture.odin · upload_rgba · opening only; continued below')
  + p(`The texture descriptor allocates one 2D, single-sample image with one mip level and one layer. <code>RGBA8UnormSrgb</code> stores four 8-bit normalized channels and decodes sRGB color to linear values when sampled; alpha remains linear. <code>TextureBinding</code> permits shader sampling. <code>CopyDst</code> permits the upload. It is not a render attachment and does not need that permission. Its format need not equal the window’s BGRA surface format: sampling produces a shader value, and the pipeline writes that value to the differently formatted attachment.`)
  + q(19,"renderer/texture.odin","    destination :=","    slot.view =","renderer/texture.odin · upload_rgba · describe and write the pixel rows","Continue inside upload_rgba, immediately after if slot.texture == nil { return 0 }. This block ends before slot.view =; append the next snippet there.")
  + p(`The destination names the texture receiving the pixels. The row layout says that each pixel occupies four bytes and each row occupies width × 4 bytes. The extent supplies the upload width and height. QueueWriteTexture accepts these tightly packed rows. For the 1254-pixel player, one row has 5016 bytes. The 256-byte row alignment required by buffer-to-texture copy commands does not apply to this queue-write operation.`)
  + p(`The call consumes/copies the CPU data for the upload before returning; it does not promise that GPU work has finished. We can free decoded pixels afterward because the implementation owns the queued transfer. Subsequent submissions to this queue observe the earlier texture writes. We do not poll the GPU after each upload.`)
  + q(19,"renderer/texture.odin","    slot.view =","\n}\n","renderer/texture.odin · upload_rgba · attach the texture and sampler","Finish upload_rgba with this block immediately after wgpu.QueueWriteTexture. Keep the allocation and upload blocks above it, then close the procedure with one closing brace.")
  + p(`The slot keeps three handles: texture storage, its view, and the bind group connecting that view and sampler to group 1. Only after all three succeed do we increase texture_count and return the nonzero ID. Failed initialization returns zero and takes the application’s shutdown path. Shutdown examines all slots, including a partly created one. We do not retry a failed load or recycle texture slots in this program.`))
  + s('Record the two rectangles', p(`First reserve the geometry storage in Init. <code>0..&lt;MAX_SPRITES</code> visits sprite numbers from zero through 255. In <code>for value, j in quad</code>, value is an index from the six-element pattern and j is its array position. Adding i × 4 moves that pattern to sprite i’s four vertices.`)
  + q(19,"renderer/renderer.odin","    indices:","    r.index_buffer =","renderer/renderer.odin · Init · generate the index pattern","Inside Init, insert this index-data block after r.vertex_buffer = wgpu.DeviceCreateBuffer and before r.index_buffer = wgpu.DeviceCreateBuffer. Keep the buffer creation and upload that follow.")
  + p(`Add Begin_Frame to reset the used count and save the world size. The recording flag catches an attempt to begin a second frame without finishing the first. The arrays stay allocated; setting count to zero makes their old contents unused.`)
  + q(19,'renderer/renderer.odin','Begin_Frame :: proc')
  + p(`Now add Sprite. The optional tint parameter defaults to white, so multiplying by it leaves the image’s color unchanged. Four local corners become four world corners through position + corner × size. The UVs select the whole image. Each call writes the next four records and saves its texture ID.`)
  + q(19,'renderer/renderer.odin','Sprite :: proc')
  + p(`Add <code>Sprite</code> to the renderer API. Between Begin_Frame and End_Frame, it writes four CPU-side vertices and one texture ID into fixed-capacity arrays. Nothing has reached the GPU yet. The room is submitted first and the player second. Their positions are independent because each sprite has its own vertex bytes; repeatedly updating a single transform uniform before one submission would instead make all draws read the final value.`)
  + p(`Each sprite needs four vertices and six indices. The renderer reserves space for 256 sprites, so the arrays hold 1024 vertices and 1536 indices. Sprite number 0 uses indices 0,1,2,0,2,3; sprite number 1 uses 4,5,6,4,6,7. The largest possible index is 1023, which fits in u16. The index array is uploaded once because this pattern does not change when pictures move.`)
  + note('A bounded API should fail visibly',`Eight texture slots include one internal white pixel, leaving seven for game images. A frame holds 256 sprites, including debug rectangles. Invalid IDs and excess sprites set a flag; End_Frame reports Fatal before uploading. Capacity is a project constraint, not an invitation to silently drop draws. There are no per-frame heap allocations in our sprite recorder.`))
  + s('Upload the list and draw in order', p(`End_Frame keeps the surface acquisition and cleanup rules from the old renderer. After a successful acquisition, it writes the world size to the view uniform and uploads only the vertices used by this frame. The number of bytes is count × 4 × size_of(Vertex). A skipped acquisition needs no vertex upload.`)
  + q(19,"renderer/renderer.odin","    uniforms :=","    encoder :=","renderer/renderer.odin · End_Frame · upload this frame’s data","Inside End_Frame, place this block after defer wgpu.TextureViewRelease(view) and before encoder :=. The surrounding surface acquisition and command encoding appear in the complete file.")
  + p(`The room must be drawn before the player. A run is a consecutive group of sprites using the same texture. End_Frame scans the texture-ID list and records one draw per run. With one room sprite followed by one player sprite, there are two runs. The first uses six indices starting at zero; the second uses six starting at six.`)
  + q(19,"renderer/renderer.odin","    // Adjacent equal textures","    wgpu.RenderPassEncoderEnd","renderer/renderer.odin · End_Frame · preserve sprite order","Inside End_Frame, place this draw loop after wgpu.RenderPassEncoderSetIndexBuffer and before wgpu.RenderPassEncoderEnd. It replaces the old single-object draw with one draw per texture run.")
  + p(`The indices already name each sprite’s own vertices, so baseVertex is zero. Group 0 remains the shared view uniform; group 1 changes to the run’s image. After the runs, End_Frame ends the pass, finishes the encoder, submits, presents, and releases frame-local references using the pattern from chapter 7.`))
  + s('Check plain geometry with the same pipeline', p(`A loaded picture combines several things: image data, UV coordinates, position, and tint. To inspect position and tint without image detail, we also keep one white texel in a texture. Init uploads {255,255,255,255} once. Sampling that texel returns white; multiplying it by a tint gives a plain rectangle of that tint.`)
  + q(19,'renderer/renderer.odin','Rect :: proc')
  + p(`Rect uses Sprite with that white texture ID. To check it after the chapter builds, temporarily add the following call after the room Sprite call in main and before the player Sprite call. You should see a red 16 × 16 rectangle near the room’s upper-left corner. Remove the diagnostic call before continuing; the Rect procedure stays available for inspecting the game.`)
  + code(`renderer.Rect(&rendering, {8, 8}, {16, 16}, {1, 0, 0, 1})`, 'odin', 'src/main.odin · temporary drawing check between the room and player calls'))
  + s('Fit a room, do not resize the world',q(19,"renderer/renderer.odin","    width, height :=","    wgpu.RenderPassEncoderSetPipeline","renderer/renderer.odin · End_Frame · viewport and scissor","Inside End_Frame, insert this viewport/scissor block after defer wgpu.RenderPassEncoderRelease(pass) and before wgpu.RenderPassEncoderSetPipeline. Keep the pass setup and draw loop.")
  + p(`Replace the window-sized game extent with 384 × 256 world units. The renderer queries physical framebuffer dimensions, chooses the smaller axis scale, rounds it down to a whole number when at least one-times scale fits, and centers a viewport. Very small windows use a fractional fit instead of cropping. Clear still initializes the entire attachment, producing dark letterbox bars. The scissor bounds writes to the viewport region; the viewport transforms coordinates, while the scissor rejects output samples outside a rectangle. Both reset with each new render pass, so both are set each frame.`)
  + p(`The room occupies the complete world rectangle. The player’s whole transparent canvas occupies 32 × 32 units. Its visible artwork uses only part of that canvas, so <code>{16,30}</code> is an authored anchor near the boots, not half the visible character’s height. We round the displayed feet position, then subtract this anchor. Simulation retains fractional movement. This avoids accumulating rounding error and establishes the foot point we will use for collision.`))
  + s('Connect the new renderer to the existing loop', p(`Replace game/game.odin with the chapter listing. Its State retains position and speed and adds room/player texture IDs. Init sets the fixed world’s starting position and speed, embeds the two PNG files, and calls Load_PNG once for each. The #load paths are relative to game/game.odin, so ../assets reaches the image directory beside game.`)
  + q(19,'game/game.odin','Init :: proc')
  + p(`The world is now 384 × 256 units. The painted floor runs roughly from x = 24 to 362 and y = 48 to 240. We keep the feet anchor between x = 28 and 358 and y = 51 and 239, leaving a small margin inside those boundaries. These are coordinates in the room, not window-dependent limits. The movement speed is 72 world units per second, chosen for that smaller room. The position marks the player’s feet rather than the rectangle’s upper-left corner. Update keeps the same direction normalization and elapsed-seconds calculation, then clamps the feet inside the floor bounds. Furniture does not affect Update yet.`)
  + p(`In main, use renderer.State and register Shutdown before calling Init. Then initialize game.State through game.Init. Move the SDL keyboard-reading procedure into main so the game receives an Input value containing only the requested direction. Its complete implementation is in src/main.odin below.`)
  + q(19,"src/main.odin","        game.Update","    }\n}","src/main.odin · replace the update/draw portion of the loop","In the replacement main procedure, place this block at the end of the running loop, immediately after the INPUT_FOCUS keyboard block. Use the complete file for the new startup, event, and input code; this excerpt replaces the old update/render sequence. Keep the closing braces of the loop and main.")
  + p(`This block updates the position, begins the drawing list, adds the room and player, and finishes the frame. Presented means an image was handed to the surface; Skipped means wait briefly and try on the next loop; Fatal means leave the loop and clean up. Resize events now call renderer.Resize to request the same surface refresh we already used. Main still owns the SDL window until renderer shutdown finishes.`)
  + p(`The room should cover the fixed world, with the player drawn over it. Moving through the table is expected at this stage. Resizing should add dark borders as needed while keeping the room’s proportions.`))
  + frame([['Decode and upload PNGs; create texture views, sampler and bind groups','Once at startup','Assets remain resident until shutdown.'],['Record sprites and upload used vertices','Once per frame','Positions can change even though image pixels do not.'],['Bind a sampled texture and draw','Once per contiguous texture run','One pipeline can sample multiple images in ordered draws.'],['Surface reconfiguration','On physical resize or recoverable outdated/suboptimal status','World coordinates and image textures do not change.']])
  + mistakes([['Opaque square around the character','Inspect source alpha and decoder desired_channels = 4; inspect blend state','A transparent file and an enabled blend equation are both required.'],['Scrambled or slanted picture','Check 32-byte stride, UV offset 8 and location 1','The shader must receive the same bytes the host wrote.'],['All sprites at the last position','Look for repeated writes to one per-object uniform before submit','Distinct geometry or distinct parameter ranges are required.'],['Blurred edges','Inspect minFilter and magFilter, and actual source asset grid','Nearest sampling prevents bilinear blending; it cannot turn inconsistent generated artwork into a hand-authored grid.']])
  + experiments(['Tint the player {1, 0.5, 0.5, 1}; leave the room white. Observe that texture color is multiplied, not replaced.','Draw the player before the opaque room. Explain why it disappears without blaming the upload.','Make the window narrower than 384 physical pixels; compare fractional fitting with the normal integer-scale viewport.'])
);

chapter(20,'a-renderer-the-game-can-use','A renderer the game can use',
  'Move scene choices into the game and keep GPU work inside the renderer.',
  'The game composes its scene through renderer.Sprite and renderer.Rect. Main coordinates systems; the renderer knows nothing about beds, movement, or characters.',
  s('What still belongs in the wrong place?',p(`The room is visible, but main still decides that the background is drawn before the player. That is game knowledge. We now move those calls into game.Draw. This is a small refactoring, not a renderer rewrite: all GPU resources, shaders, and batching behavior introduced in chapter 19 remain unchanged. Running this checkpoint should look identical to the previous one.`)
  + flow('Dependencies point toward a reusable service; data does not flow back into simulation.',['SDL events','main → Input','game.Update','game.Draw','renderer API'])
  + table(['Owner','Knows about','Must not decide'],[
    ['main package','SDL window, elapsed time, input translation, lifetime ordering','Which image represents the room or where a character is drawn.'],
    ['game package','Room extent, asset choices, position, speed, scene order','WebGPU handles, surface formats, bind groups, or command encoding.'],
    ['renderer package','Textures, sprite vertices, buffers, pipelines, surface and presentation','What movement keys mean, whether a table is solid, or where the player should stand.'],
  ]))
  + s('What each renderer call needs and does',table(['Procedure','Precondition / input','Effect / result'],[
    ['Init(&r, window)','Zero-initialized, stable-address State; live SDL window','Creates native/GPU resources. On false, still call Shutdown.'],
    ['Load_PNG(&r, bytes)','Initialized renderer, trusted bytes, outside a frame','Uploads once; returns stable nonzero texture ID, or zero on fatal startup failure.'],
    ['Resize(&r)','Renderer is alive','Marks surface configuration dirty; does not touch game state.'],
    ['Begin_Frame(&r, world_size)','No frame currently recording; positive finite extent','Starts a fresh CPU-side sprite list. Does not acquire a surface image.'],
    ['Sprite(&r, id, position, size, tint)','Recording frame, renderer-owned ID, positive size','Appends one image quad by value; preserves call order.'],
    ['Rect(&r, position, size, color)','Same recording contract','Uses the renderer’s white texture and Sprite machinery.'],
    ['End_Frame(&r)','Exactly one open frame','Uploads, encodes, submits and presents, or returns Skipped/Fatal. Closes recording on every path.'],
    ['Shutdown(&r)','Main thread; no more use afterward','Waits at shutdown, releases owned objects, handles partial initialization.'],
  ]) + p(`A returned texture ID is meaningful only in the renderer that issued it, until that renderer shuts down. The integer is not a portable asset identifier and cannot be serialized as a persistent save-game reference. The renderer owns the native resources; game.Init selects which files to load. All calls remain on SDL’s main thread. Do not copy an initialized renderer State: copying native handles does not add references, and double shutdown would release ownership twice.`)
  + p(`Odin makes these fields visible, but game code will use the renderer procedures instead of editing the fields. Check that game/game.odin has no wgpu import and does not change renderer.State internals. Keeping that rule in application code protects the renderer’s ownership decisions. Tests may inspect the CPU arrays to check what those procedures recorded.`))
  + s('Move composition, keep behavior',p(`In <code>src/main.odin</code>, remove the two Sprite calls and the local feet calculation, and remove the now-unused math import. Replace that block with <code>game.Draw(&world, &rendering)</code>. Add the following procedure at the end of <code>game/game.odin</code>. The exact patch below shows both sides of this move.`)
  + q(20,'game/game.odin','Draw :: proc')
  + p(`The game chooses draw order and the player’s visual anchor. It asks the renderer for an image at a location, not for a command encoder. Drawing does not change world.position. The local snapped coordinate is a temporary presentation choice; the next update still starts with the unsnapped floating-point state. This separation makes a screenshot, a skipped presentation, or a future second view incapable of advancing simulation accidentally.`)
  + q(20,"src/main.odin","        game.Update","    }\n}","src/main.odin · main · update and draw inside the running loop","Inside main, replace the tail of the running loop from game.Update through the final if result == .Skipped check with this block. Keep the event/input/timing code and both enclosing closing braces.")
  + p(`The main loop still reads events and keys, measures elapsed time, and updates the game. It then begins a drawing list, calls game.Draw, and ends the frame. End_Frame acquires the surface image after the list is built. If acquisition returns a recoverable skip, main waits briefly and the next loop starts a fresh list. Fatal errors leave the loop and run the same deferred cleanup used for startup failures.`))
  + s('Why this batch is modest and correct',q(20,"renderer/renderer.odin","    // Adjacent equal textures","    wgpu.RenderPassEncoderEnd","renderer/renderer.odin · End_Frame · unchanged texture-run drawing","Read this unchanged block inside End_Frame, between wgpu.RenderPassEncoderSetIndexBuffer and wgpu.RenderPassEncoderEnd. No renderer edit is needed in this chapter.")
  + p(`The renderer uploads one vertex prefix, then groups only consecutive sprites with the same texture. For [room, player, white, white], the sequence has three draws. For [room, player, room], it has three draws, not two. Sorting by texture would reduce some state changes but alter painter’s order. Our alpha blend is order-dependent: a translucent later sprite sees the framebuffer color from earlier sprites. Correct composition is more important than minimizing an already tiny number of binds.`)
  + p(`Every run binds group 1 before DrawIndexed. Group 0 and the vertex/index buffers remain selected across runs. Render-pass state is recorded, so each draw uses the state selected at that point in the command stream. CPU sprite recording and WebGPU command recording are separate stages: Sprite fills ordinary Odin arrays, while End_Frame turns those arrays into GPU data and draw commands. A command buffer is still submitted once; batching has not made rendering immediate.`)
  + p(`The renderer currently accepts whole images, translation, size, and tint. It uses one blend rule, preserves call order, and keeps each loaded image until shutdown. These limits match the room we have built. Add another option when a game feature needs it, then define what that option means for drawing and cleanup.`))
  + s('Ownership you can audit',table(['Item','Owner','Lifetime'],[
    ['Embedded PNG bytes','Executable/static data','Process; immutable build input.'],
    ['Decoded RGBA allocation','Load_PNG','Only until QueueWriteTexture returns.'],
    ['Texture, texture view, texture bind group','renderer.State slot','Initialization through Shutdown.'],
    ['Sampler, pipeline, three GPU buffers','renderer.State','Many frames; no rebuild for a size-only resize.'],
    ['Texture_ID in game.State','Game stores a borrowed identifier','Only while owning renderer is alive.'],
    ['CPU vertex prefix and texture-ID list','renderer.State','Storage reused every frame; contents overwritten by Begin/Sprite.'],
    ['Acquired surface texture/view and encoding objects','End_Frame','One frame; defer releases on every return path.'],
  ]) + p(`Shutdown polls for completion once, then releases game image groups before their views and textures, followed by the sampler, layouts, buffers, pipeline, and connection. Native reference tracking also retains dependencies as required, but an explicit readable order helps auditing. The unchanged GPU teardown includes a conservative second completion poll before surface/device destruction; it is redundant after the renderer wait, not a per-frame synchronization strategy. Never move those waits into End_Frame merely to feel safer.`)
  + note('One renderer instance in this program',`The inherited diagnostic callback uses process-lifetime fault storage. This application initializes one renderer and exits on a device fault. The API is not advertised as restartable after device loss or as a multi-device engine service. Supporting those cases would require a different callback/state lifetime contract, not just calling Init a second time.`))
  + s('Choose where the next change belongs',p(`The two packages answer different questions. game.Draw decides which picture belongs behind another. End_Frame decides how to bind that picture and record its draw. Keeping those decisions separate gives each change a clear home. We can add a game object without adding a new kind of graphics resource, and repair an upload without changing movement rules.`)
  + p(`The renderer is general enough for this project’s sprites and diagnostic rectangles, and no more. When a feature is missing, first ask whether it belongs to scene policy or GPU mechanism. “Draw the player after the room” belongs to game.Draw. “Bind the player’s texture view before its indexed draw” belongs to End_Frame. “A chair blocks the character’s feet” belongs to simulation, which we will add next.`))
  + frame([['Choose and load room/player assets','Once in game.Init','Game selects content; renderer owns GPU residency.'],['game.Update','Once per active loop iteration','Only simulation changes position.'],['game.Draw / Sprite','Once per frame / once per requested image','Describes appearance without advancing time.'],['Texture group switch','Once per contiguous texture run','Preserves alpha order while avoiding redundant adjacent binds.']])
  + mistakes([['Game starts importing vendor:wgpu','Check whether a missing renderer operation caused the leak','Expose a small drawing operation instead of handing game code the GPU device.'],['A skipped frame causes a movement jump','Check that game.Draw does not update position','Update count and presentation count are independent.'],['Double release after passing State by value','Inspect whether renderer ownership was copied','Pass a pointer to the one initialized owner.']])
  + experiments(['Add a small translucent Rect after the player in game.Draw; then move it before the player. Keep renderer code unchanged.','Record room, player, room and trace the three texture runs. Explain the final image before running.','Temporarily set MAX_SPRITES to 1 and run. Confirm that exceeding the contract produces a diagnostic instead of an incomplete frame.'])
);

chapter(21,'solid-furniture','Solid furniture, simple collision',
  'A picture can suggest a solid table. Only game rules make it solid.',
  'The character stops at room walls and furniture, slides along edges, and cannot tunnel through thin obstacles with a large axis step.',
  s('Two representations of one room',p(`Our character can currently cross the bed. The renderer is doing exactly what we asked: it draws pictures. It has no concept of furniture. We will add a small list of axis-aligned solid rectangles to the game package and constrain the player’s movement against them. No WebGPU descriptor changes, no shader changes, and no collision logic inside the renderer are necessary.`)
  + p(`An axis-aligned bounding box, or AABB, is a rectangle described by minimum corner and size, with edges parallel to the world axes. We use one compact AABB around the player’s feet, not the full transparent image canvas. A top-down character has visual height, but stands on a much smaller ground footprint. Using the 32 × 32 sprite rectangle would collide against empty transparency and make door-sized gaps feel arbitrarily narrow.`)
  + `<figure class="room-collision-map"><div class="room-map"><img src="../project/assets/room.png" width="1536" height="1024" alt="Room artwork under an authored collision overlay"><svg viewBox="0 0 384 256" aria-label="Orange outlines mark walls and furniture; green marks the starting feet"><g fill="rgba(255,90,35,.12)" stroke="#ff6b35" stroke-width="1"><rect width="384" height="48"/><rect y="240" width="384" height="16"/><rect y="48" width="24" height="192"/><rect x="362" y="48" width="22" height="192"/><rect x="26" y="24" width="65" height="118"/><rect x="90" y="41" width="27" height="34"/><rect x="300" y="16" width="60" height="65"/><rect x="274" y="90" width="84" height="60"/><rect x="295" y="134" width="31" height="38"/><rect x="26" y="160" width="54" height="40"/><rect x="17" y="196" width="33" height="39"/></g><rect x="188" y="202" width="8" height="4" fill="none" stroke="#65ff97" stroke-width="1"/></svg></div><figcaption>Gameplay geometry is an authored approximation. The rug remains walkable; the bottom doorway is decorative.</figcaption></figure>`
  + p(`The artwork is flattened into one background texture. We therefore do not implement walking behind separately sorted furniture layers. The small feet box lets the character’s upper body visually overlap furniture fronts, which is conventional for a top-down ground footprint. The collision rectangles are conservative authoring choices, not pixel-perfect silhouette tests. For true behind-furniture occlusion, the art would need separate layers and an explicit ordering policy; that is a different feature.`))
  + s('Add explicit room geometry',p(`Add <code>game/collision.odin</code> to the game package. Its world units are the same units used by game.position and WORLD_SIZE. To author against the supplied room, divide source-image x and y by four: 1536/384 = 1024/256 = 4. Do not divide by the current window scale. Resizing the window cannot move a bed in game space.`)
  + q(21,"game/collision.odin","Box :: struct","Feet :: proc","game/collision.odin · Box and SOLIDS · collision geometry","Create game/collision.odin with package game on its first line. Add Box and SOLIDS at file scope, then append Feet, Overlaps, and Move from the following snippets.")
  + q(21,'game/collision.odin','Feet :: proc')
  + p(`The feet box runs from position − (4,3) to position + (4,1). Thus position is a near-boot anchor, not the box’s top-left corner. Four wall rectangles enclose a floor with x from 24 to 362 and y from 48 to 240. The character’s center can reach x = 358 at the east wall because its right edge is four units farther right. It reaches y = 51 at the north wall because its top edge is three units above the anchor. These numbers follow from geometry; they are not unexplained clamp constants.`)
  + p(`The bed overlaps the north wall and the bedside table overlaps the bed slightly; overlapping static obstacles are fine. SOLIDS is addressable package storage so Odin can pass a slice without copying the list every update. We treat it as read-only after initialization. There is no per-frame allocation, spatial tree, or physics library: eleven boxes are cheap enough to inspect directly.`)
  + q(21,'game/collision.odin','Overlaps :: proc')
  + p(`Strict inequalities mean touching edges are not penetration. Two rectangles overlap only if they share a positive interval on both axes. This helper is useful in tests and spawn validation, but a final-position overlap test alone is not enough for movement: a large step could begin before a thin table and end beyond it without either endpoint overlapping.`))
  + s('Clip movement before crossing an edge',p(`Suppose the feet anchor is at x = 40 and the feet extend four units to the right. Their right edge is 44. An obstacle starts at x = 100, so only 100 − 44 = 56 units of rightward travel are available. A request for 1000 units must be shortened to 56, leaving the anchor at 96. We will apply this calculation to every relevant obstacle and keep the smallest allowed movement.`)
  + p(`The loop handles horizontal movement first, then vertical movement. axis is 0 for x and 1 for y; other = 1 − axis selects the other coordinate. continue skips an obstacle when the feet do not overlap it on that other axis. min limits a positive step; max limits a negative step toward zero.`)
  + q(21,'game/collision.odin','Move :: proc')
  + p(`For each axis, calculate how far movement may proceed before the first obstacle edge. On X, first reject every solid whose Y interval does not overlap the feet. For a positive X move, an obstacle is ahead if the feet’s right edge is at or left of its left edge. The permitted distance is at most obstacle.left − feet.right. Take the minimum over all candidates. For a negative move, use feet.left and obstacle.right and take the maximum negative distance. Obstacles farther away than the desired step cannot reduce it.`)
  + p(`Apply that resolved X displacement, rebuild the feet from the new position, and repeat on Y. When one axis is blocked, the other may still move: that is wall sliding. Starting exactly at an edge yields a permitted zero step toward the wall but does not prevent stepping away. Because we compare crossed edges, a 1000-unit axis step still stops at the nearest solid rather than tunneling through it.`)
  + table(['Example','Calculation','Result'],[
    ['Feet center x=40, width 8; obstacle begins x=100; requested dx=1000','Right edge=44; allowed=min(1000,100−44)=56','New center x=96; right edge touches 100.'],
    ['Feet center x=200; obstacle ends x=120; requested dx=−1000','Left edge=196; allowed=max(−1000,120−196)=−76','New center x=124; left edge touches 120.'],
    ['Already touching the west side; request (20,20)','X is clipped to zero; Y is evaluated from resolved X','Slide down the side if no other obstacle blocks Y.'],
  ]) + note('The actual guarantee',`This is axis-separated swept collision, not continuous diagonal time-of-impact physics. It resolves an X segment followed by a Y segment; the order introduces a corner bias. It prevents crossings along those resolved segments for a non-overlapping start and static AABBs. It does not recover embedded spawns, push moving obstacles, resolve rotation, or model acceleration/impulses. Those limitations are acceptable for one keyboard-controlled room character.`))
  + s('Connect the simulation, not the drawing code',p(`In <code>game.Update</code>, replace the old position addition and floor clamps with <code>Move(&g.position, delta, SOLIDS[:])</code>. Leave normalization, speed, and seconds-based delta calculation in place. The collision function receives requested world displacement, not raw keyboard state, so it can be tested without SDL.`)
  + q(21,'game/game.odin','Update :: proc')
  + p(`Normalize diagonal keyboard input before multiplying by speed and dt. Resolving a blocked component afterward naturally reduces total distance while sliding into a wall; do not renormalize the surviving displacement unless you deliberately want a different movement feel. Main still caps unusually long elapsed intervals at 0.05 seconds to avoid a huge catch-up jump after a stall. The collision routine itself is tested with much larger steps so its correctness is not dependent on that cap.`)
  + p(`The renderer receives the resulting position through exactly the same Draw call as before. It does not read SOLIDS. When the player reaches a chair, the GPU sees identical character vertices on subsequent blocked updates. Collision does not stop a shader, modify a texture, or ask the GPU whether two pictures intersect.`))
  + collisionTestLesson
  + frame([['Define static solid rectangles','Once as game data','No texture scan or GPU readback is necessary.'],['Clip X then Y against solid rectangles','Once per update','Work scales with this tiny fixed obstacle list.'],['Draw the resolved character position','Once per frame','Same renderer API and GPU pipeline as before.'],['Resize the window','No collision work','The fixed world does not depend on framebuffer size.']])
  + mistakes([['Stops far from furniture','Compare the feet box and authored solid with the visual canvas','Transparent padding and sprite height are not ground footprint.'],['Teleports through a thin object','Check whether only the final position was tested','Crossed edges must constrain displacement.'],['Cannot move away from a wall','Inspect sign tests and touching-edge rules','An edge should restrict motion into the solid, not out of contact.'],['Spawns inside a bed and behaves strangely','Validate initial feet against all solids','This solver assumes nonpenetrating starts; it is not an overlap-recovery system.']])
  + experiments(['Move the spawn to an open spot and verify it against every solid before running. Then deliberately choose a bed position and explain why that violates the solver contract.','Temporarily increase speed to 720. Verify that walls still stop the player, and distinguish collision correctness from unpleasant movement feel.','Change the rug from walkable to solid by adding one authored box. No renderer changes should be necessary.'])
);

chapter(22,'finish-with-evidence','Finish with evidence',
  'Add a collision overlay, audit failure paths, and follow one input all the way through the finished room renderer.',
  'This checkpoint has a pixel-art room, a movable pixel-art character, furniture collision, a resizable letterboxed view, a small renderer API, and F1 collision diagnostics.',
  s('Make invisible rules visible',p(`The collision rules work with numbers, but comparing eleven rectangles with a picture is awkward. We will add an F1 overlay that draws those rectangles over the room. Orange outlines show solid regions, and a green outline shows the player’s feet. The existing Rect procedure can draw every line, so the renderer needs no new feature.`)
  + p(`In main’s event switch, add the KEY_DOWN case shown below. This is edge-triggered input: toggle once for the press event, ignoring OS key-repeat events. Movement still uses held keyboard state after polling. Those are different input semantics, and both are translated into game.Input before Update.`)
  + q(22,"src/main.odin","            case .KEY_DOWN:","            }\n        }","src/main.odin · main · add the F1 event case","Inside main, add this case to switch event.type in the sdl.PollEvent loop, after the window-resize case and before the switch closing brace. Keep the existing cases.")
  + p(`Add <code>toggle_collision: bool</code> to Input and <code>show_collision: bool</code> to game.State. Update flips the retained state when the input edge is present. Main creates a fresh zeroed Input each loop, so the edge does not remain asserted on following frames. The scene overlay belongs in game.Draw, after the room and character, ensuring its lines remain visible.`)
  + q(22,'game/game.odin','Draw :: proc')
  + q(22,'game/game.odin','outline :: proc')
  + p(`An outline is four thin filled rectangles. Rect uses a one-pixel white texture created by renderer.Init; multiplication by tint supplies each line’s color. All overlay rectangles share that texture and are consecutive, so they form one texture run after the room and player runs. Eleven solid outlines plus one feet outline need 48 rectangles; with the two scene sprites, the total is 50, comfortably below 256. Their corners overlap slightly under alpha blending; this is diagnostic geometry, not an exact single-coverage stroked-path renderer.`)
  + p(`The feet outline uses the unsnapped simulation position while the player sprite uses rounded display coordinates. A sub-unit discrepancy is intentional and helps reveal the distinction between collision truth and visual snapping. If a table looks too large or a plant can be approached too closely, adjust the authored game box with this view, then update the corresponding regression test where appropriate.`))
  + s('From main to a furnished window',flow('The finished application, without a hidden engine.',['SDL window','renderer.Init','game.Init','events / update','game.Draw','End_Frame'])
  + list([
    '<strong>Startup:</strong> main initializes SDL video, creates and shows the native window, and retains it until after renderer shutdown. No SDL Renderer is created.',
    '<strong>Native connection:</strong> renderer.Init invokes our unchanged platform and GPU code: instance → surface → compatible adapter → logical device → queue → capabilities and surface configuration. A size-only change later updates the configuration, not the asset set.',
    '<strong>Rendering interface:</strong> Init creates vertex/index/view buffers, two bind group layouts, a nearest sampler, shader module and render pipeline, the view bind group, and an internal white texture. The shader module’s temporary application reference is released after pipeline creation.',
    '<strong>Game assets:</strong> game.Init sets the spawn and speed, embeds and decodes the room/player PNGs through Load_PNG, and stores the two returned texture IDs. Each texture upload creates persistent sampled storage, view, and bind group.',
    '<strong>Simulation:</strong> main pumps SDL events, constructs Input, computes capped dt, and calls game.Update. Update normalizes direction and clips the requested displacement against the authored solids.',
    '<strong>Scene description:</strong> Begin_Frame resets reusable CPU recording storage. game.Draw appends the background, the snapped player quad, and optionally diagnostic rectangles.',
    '<strong>Actual frame:</strong> End_Frame processes native callbacks, refreshes physical surface size if needed, acquires the current image, creates its view, uploads current vertices/view data, records an ordered render pass, finishes, submits, and presents.',
    '<strong>Cleanup:</strong> per-frame handles are released via defer. Closing the window or encountering an unrecoverable error unwinds persistent renderer resources before SDL destroys the window and quits.',
  ]))
  + s('One D press, traced precisely',p(`SDL pumps the keyboard event and updates its held-key array. If this window has input focus, main translates D into movement.x = 1. At speed 72 world units/second and dt = 1/60, the requested displacement is 1.2 world units to the right. Update asks Move to clip that X segment, then its zero Y segment. In open floor space the entire 1.2 units is accepted; against a chair only the remaining gap is accepted, possibly zero.`)
  + p(`Draw rounds a copy of that resolved foot position and subtracts the sprite’s visual anchor. Sprite expands its four world-space corners and their UVs into CPU vertices. End_Frame writes those bytes into the existing GPU vertex buffer; it does not upload the player PNG again. Queue order makes this frame’s writes visible to the following render commands. The vertex shader maps the new corners into clip space; the viewport maps NDC into the centered physical image region.`)
  + p(`Rasterization determines covered samples and interpolates UV and tint. The fragment shader samples the persistent player texture, yielding linear RGB and straight alpha. The pipeline blends it over the previously drawn room in the sRGB surface attachment. Submit hands the recorded work to the GPU queue, Present hands the surface image back to the presentation system, and the display eventually shows the new frame. Neither call proves the monitor has already scanned out the image.`)
  + p(`If collision returns zero movement, the same vertices are sent again and the character stays against the chair. If acquisition returns Occluded or Timeout, no visible frame is produced; the simulation and window lifecycle remain CPU responsibilities. “I pressed D but nothing moved” can now be localized: input focus/state, dt, collision result, recorded vertices, queue upload, shader transform, or actual surface presentation.`))
  + s('Validate layers independently',table(['Check','What it proves','What it cannot prove'],[
    ['odin build … -vet','Host syntax/types, imports, embedded file presence, native linkage','WGSL pipeline validation or visible output.'],
    ['The tests created in chapter 21','Deterministic collision, movement, and CPU recorder checks','A driver accepted the shader or the artwork looks aligned.'],
    ['F1 overlay + manual play','Authored geometry and visible placement can be inspected together','All large-step and edge cases without deterministic tests.'],
  ]) + p(`Repeat the chapter 21 test command after adding the overlay; the same eight checks should pass. Then run the application. Approach the chair from below: the feet anchor should stop at y = 175. Approach the north wall in the open middle of the room: it should stop at y = 51. Toggle F1 to see the feet box touch the corresponding solid edge. These are the same contacts checked numerically by the tests.`)
  + p(`A manual acceptance pass remains valuable: hold each direction and diagonal; release keys; switch focus away and back; approach both sides of the bed and table; slide past the chair; toggle F1; resize to a narrow window; minimize and restore; close normally. Test on each shipping platform with its actual backend and high-DPI behavior. The provided Windows and Linux branches are not claimed as runtime-verified by the macOS run.`))
  + s('Small production habits to keep',list([
    'Keep the image files with your project and retain the matching compiler and library versions.',
    'Keep a playable checkpoint. Add one behavior and one focused test before expanding the renderer API.',
    'Name coordinate units and sprite anchors. Do not let window pixels silently become collision coordinates.',
    'Make capacity limits and ownership visible. A small explicit limit is better understood than accidental unbounded work.',
    'Distinguish diagnostics from recovery. Device/surface loss exits this program; automatic recreation is not implemented.',
    'Use evidence from the failing layer. A unit test cannot certify a native frame, and a screenshot cannot certify a swept collision guarantee.',
  ]) + p(`This checkpoint completes the room’s collision and diagnostics. Chapter 23 adds the final directional animation while retaining the same renderer boundary and collision rules. The renderer is a service the game can use, not the owner of the game. You can now change the room’s content and movement rules without re-learning WebGPU initialization, and change how sprites become GPU work without moving collision into a shader. That is a useful professional foundation because the boundaries are understandable and testable.`))
  + frame([['Toggle diagnostic state','On a nonrepeated F1 press','An event edge differs from held movement input.'],['Outline solids/feet','Per frame when diagnostics are enabled','Uses existing sprite buffers/pipeline and one additional texture run.'],['Collision resolution','Per update, before Draw','GPU never decides gameplay penetration.'],['Wait for GPU completion','At shutdown only','Native references and queue ordering handle normal overlapping CPU/GPU work.']])
  + mistakes([['Overlay appears behind the room','Check game.Draw ordering','Diagnostics must be appended after opaque background draws.'],['F1 flickers repeatedly while held','Check event.key.repeat and fresh Input initialization','A toggle consumes a press edge, not a held boolean.'],['Tests pass but a window is black','Count successful acquisitions/presents and read native diagnostics','Loop iterations do not prove any image was rendered.'],['Art and collision disagree after editing assets','Recheck source-to-world scale and authored boxes','Generated artwork does not automatically update game geometry.']])
  + experiments(['Adjust one furniture collider while watching F1, then encode the desired contact position in a test.','Add a non-solid decoration with Sprite or Rect without changing Update. Explain why it has no collision until explicitly authored.','Trace the same D press while pressed against the chair: identify exactly which values stop changing and which frame operations still occur.'])
);
